 格式化默认值 */ private static String defaultValue(String value) &#123; if (StringUtils.isNotBlank(value)) {return “；默认值：” + value;}{return “”;} private static String getAliasName(String tableName,String prefix)&#123; return tableName.substring(prefix.length()); } /** * 格式化数据类型 * 返回的是基本类型的包装类 * 如果使用基本数据类型long */ private static String formatType(String typeValue) &#123; if (“bit”.equalsIgnoreCase(typeValue)) {return “Boolean”;}else if (typeValue.equalsIgnoreCase(“int”) || typeValue.equalsIgnoreCase(“int unsigned”)|| typeValue.equalsIgnoreCase(“tinyint”) || typeValue.equalsIgnoreCase(“tinyint unsigned”)|| typeValue.equalsIgnoreCase(“smallint”) || typeValue.equalsIgnoreCase(“smallint unsigned”)|| typeValue.equalsIgnoreCase(“mediumint”) || typeValue.equalsIgnoreCase(“mediumint unsigned”)) {return “Integer”;} else if (typeValue.equalsIgnoreCase(“bigint”) || typeValue.equalsIgnoreCase(“bigint unsigned”)) {return “Long”;} else if (typeValue.equalsIgnoreCase(“float”) || typeValue.equalsIgnoreCase(“float unsigned”)) {return “Float”;} else if (typeValue.equalsIgnoreCase(“decimal”) || typeValue.equalsIgnoreCase(“decimal unsigned”) || typeValue.equalsIgnoreCase(“numeric”) || typeValue.equalsIgnoreCase(“numeric unsigned”)|| typeValue.equalsIgnoreCase(“real”) || typeValue.equalsIgnoreCase(“real unsigned”) || typeValue.equalsIgnoreCase(“money”) || typeValue.equalsIgnoreCase(“money unsigned”)|| typeValue.equalsIgnoreCase(“smallmoney”) || typeValue.equalsIgnoreCase(“smallmoney unsigned”)) {return “Double”;} else if (typeValue.equalsIgnoreCase(“varchar”) || typeValue.equalsIgnoreCase(“char”)|| typeValue.equalsIgnoreCase(“nvarchar”) || typeValue.equalsIgnoreCase(“nchar”)|| typeValue.equalsIgnoreCase(“text”)) {return “String”;} else if (typeValue.equalsIgnoreCase(“datetime”)) {return “Date”;} else if (typeValue.equalsIgnoreCase(“image”)) {return “Blod”;} else {} &#125; /** * 驼峰转换 */ private static String columnToProperty(String column) &#123; StringBuilder result &#x3D; new StringBuilder();&#x2F;&#x2F; 快速检查if (column &#x3D;&#x3D; null || column.isEmpty()) {&#x2F;&#x2F; 没必要转换return “”;}else column &#x3D;column.toLowerCase(); if (!column.contains(““)) {&#x2F;&#x2F; 不含下划线，仅将首字母小写return column.substring(0, 1).toLowerCase() + column.substring(1);&#x2F;&#x2F; 用下划线将原始字符串分割String[] columns &#x3D; column.split(““);for (String columnSplit : columns) {&#x2F;&#x2F; 跳过原始字符串中开头、结尾的下换线或双重下划线if (columnSplit.isEmpty()) {continue;}&#x2F;&#x2F; 处理真正的驼峰片段if (result.length() &#x3D;&#x3D; 0) {&#x2F;&#x2F; 第一个驼峰片段，全部字母都小写result.append(columnSplit.toLowerCase());&#x2F;&#x2F; 其他的驼峰片段，首字母大写result.append(columnSplit.substring(0, 1).toUpperCase()).append(columnSplit.substring(1).toLowerCase());}return result.toString();} /** * 实体名称转换 */ private static String formatBeanName(String column) &#123; } else if (!column.contains(“_”)) {&#x2F;&#x2F; 不含下划线，仅将首字母大写return column.substring(0, 1).toUpperCase() + column.substring(1);}}} /** * 实体类字段 */ private static void getBean(String tableName,String aliasName) &#123; getConnection &#x3D; getConnections();StringBuilder sb &#x3D; new StringBuilder();try {DatabaseMetaData dbmd &#x3D; getConnection.getMetaData();ResultSet rs &#x3D; dbmd.getColumns(null, “%”, tableName, “%”);String beanName &#x3D; formatBeanName(aliasName);sb.append(“package “+packageName+”.entity;

